const clientData = $('Loop Over Clients').item.json;
const postsToday = parseInt($input.first().json.posts_today || 0) || 0;
const pendingApprovals = parseInt($input.first().json.pending_approvals || 0) || 0;
const dailyLimit = parseInt($input.first().json.daily_post_limit || 3) || 3;

console.log('CLIENT:', clientData.client_id, '| posts_today:', postsToday, '| daily_limit:', dailyLimit);

// CHANGE 2: Respect auto_gen_enabled flag — skip if user has paused auto-generation
const autoGenEnabled = clientData.auto_gen_enabled;
if (autoGenEnabled === false) {
  return [{ json: {
    skip: true,
    reason: 'Auto-generation disabled by user',
    client_id: clientData.client_id
  }}];
}

if (postsToday >= dailyLimit) {
  return [{ json: { skip: true, reason: 'Daily limit reached', client_id: clientData.client_id } }];
}

if (pendingApprovals >= 3) {
  return [{ json: { skip: true, reason: 'Too many pending approvals', client_id: clientData.client_id } }];
}

const remaining = dailyLimit - postsToday;
// CHANGE 1: Always generate exactly 1 post per run (was: 2 in morning, 1 in evening)
const targetCount = Math.min(1, remaining);

return [{
  json: {
    skip: false,
    client_id: clientData.client_id,
    name: clientData.name,
    target_post_count: targetCount,
    posts_today: postsToday,
    daily_limit: dailyLimit,
    run_type: 'standard'
  }
}];

// Fetch dynamic client profile from Flask API
// This replaces all hardcoded HR prompt logic

const data = $input.first().json;
const clientId = data.client_id;
const idea = data.idea || null;  // present when triggered via Generate from Idea
const apiUrl = `http://localhost:5050/api/client-profile/${clientId}`;

let profileData;
try {
  const response = await fetch(apiUrl);
  if (!response.ok) {
    throw new Error(`Flask API returned ${response.status}`);
  }
  profileData = await response.json();
} catch(e) {
  console.error('Failed to fetch client profile:', e.message);
  profileData = {
    status: 'ok',
    name: data.name,
    system_prompt: `You are a LinkedIn content writer for ${data.name}. Write engaging professional posts. Return valid JSON array only.`,
    topic_pillars: ['Professional Growth', 'Industry Insights', 'Leadership', 'Career Tips', 'Workplace Culture'],
    post_formats: ['story', 'insight', 'tips']
  };
}

const pillars = profileData.topic_pillars || [];
const formats = profileData.post_formats || ['story', 'insight', 'tips'];
const targetCount = idea ? 1 : (data.target_post_count || 1);

let userPrompt;

if (idea) {
  // ── Idea-based generation ────────────────────────────────────────────
  // The user provided a raw idea. It may be rough, grammatically incorrect,
  // in a mix of languages, or missing detail. Our job is to understand the
  // core intent and write a polished LinkedIn post from it.

  // Pick a format that fits the idea best (rotate by hour for variety)
  const hour = new Date().getHours();
  const chosenFormat = formats[hour % formats.length];
  const chosenPillar = pillars[Math.floor(Date.now() / 86400000) % pillars.length];

  userPrompt = `A user wants to share the following idea as a LinkedIn post. Their description may be rough, poorly worded, in mixed language, or incomplete — your job is to understand WHAT THEY MEAN, not just what they wrote.

USER'S RAW IDEA:
"${idea}"

INSTRUCTIONS:
1. Read the idea carefully and identify the core message the user wants to convey.
2. Write a polished, compelling LinkedIn post that expresses that core message authentically.
3. The post should sound like the author's own voice (defined in your system prompt).
4. If the idea maps naturally to a topic pillar, use it — otherwise choose the most relevant one from: ${pillars.join(', ')}.
5. Choose the best post format from: ${formats.join(', ')}. Suggested: ${chosenFormat}.

FORMAT GUIDE:
- story: Personal experience → tension → lesson (150-250 words)
- insight: Bold observation → why it matters → fresh perspective (100-200 words)
- tips: Problem/promise → 3-5 specific actionable tips → outcome (150-250 words)
- controversial: Unpopular opinion → acknowledge common belief → your reasoning (150-250 words)
- lessons: Mistake/challenge → what happened → 2-3 lessons learned (150-250 words)

QUALITY RULES:
1. First line MUST stop the scroll
2. Short paragraphs — max 3 lines, use line breaks
3. Never start with "I"
4. Sound human — vary sentence length
5. No clichés: 'game-changer', 'excited to share', 'in today's world'
6. No hashtags, no emojis
7. Stay true to the user's original intent

Return a JSON array with exactly 1 object:
[
  {
    "content": "complete post text with \\n for line breaks",
    "topic_pillar": "the topic this post belongs to",
    "post_format": "the format used",
    "hook": "just the first line",
    "estimated_words": 180
  }
]`;

} else {
  // ── Standard pillar-based generation ────────────────────────────────
  const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
  const selectedPillars = [];
  const selectedFormats = [];

  for (let i = 0; i < targetCount; i++) {
    selectedPillars.push(pillars[(dayOfYear + i) % pillars.length]);
    selectedFormats.push(formats[(dayOfYear + i) % formats.length]);
  }

  const postsRequest = selectedPillars.map((pillar, i) =>
    `Post ${i+1}: Topic="${pillar}" Format="${selectedFormats[i]}"`
  ).join('\n');

  userPrompt = `Create ${targetCount} LinkedIn post(s) as specified below.

POSTS TO GENERATE:
${postsRequest}

FORMAT GUIDE:
- story: Personal experience → tension → lesson (150-250 words)
- insight: Bold observation → why it matters → fresh perspective (100-200 words)
- tips: Problem/promise → 3-5 specific actionable tips → outcome (150-250 words)
- controversial: Unpopular opinion → acknowledge common belief → your reasoning (150-250 words)
- lessons: Mistake/challenge → what happened → 2-3 lessons learned (150-250 words)

QUALITY RULES:
1. First line MUST stop the scroll
2. Short paragraphs — max 3 lines, use line breaks
3. Never start with the word "I"
4. Sound human — vary sentence length
5. No cliches: 'game-changer', 'excited to share', 'in today's world'
6. No hashtags, no emojis
7. Each post on a DIFFERENT topic

Return a JSON array with exactly ${targetCount} object(s):
[
  {
    "content": "complete post text with \\n for line breaks",
    "topic_pillar": "exact topic from above",
    "post_format": "exact format from above",
    "hook": "just the first line",
    "estimated_words": 150
  }
]`;
}

return [{
  json: {
    system_prompt: profileData.system_prompt,
    user_prompt: userPrompt,
    client_id: data.client_id,
    target_post_count: targetCount,
    generation_mode: idea ? 'idea' : 'standard'
  }
}];

// Parse AI response into individual post objects
const agentOutput = $input.first().json.output || $input.first().json.text || '';
const generationData = $('Build Generation Prompt').item.json;

console.log('Raw AI output length:', agentOutput.length);

// Clean the output — remove markdown code blocks if present
let cleanOutput = agentOutput
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

// Extract JSON array
const jsonMatch = cleanOutput.match(/\[\s*\{[\s\S]*\}\s*\]/);
if (!jsonMatch) {
  console.error('No JSON array found in output:', cleanOutput.substring(0, 200));
  return [{ json: { error: 'No valid JSON in AI response', raw: cleanOutput.substring(0, 500) } }];
}

let posts;
try {
  posts = JSON.parse(jsonMatch[0]);
} catch(e) {
  console.error('JSON parse error:', e.message);
  return [{ json: { error: 'Failed to parse AI response', raw: cleanOutput.substring(0, 500) } }];
}

if (!Array.isArray(posts) || posts.length === 0) {
  return [{ json: { error: 'Empty posts array from AI' } }];
}

// Map each post with client context
return posts.map(post => ({
  json: {
    client_id: generationData.client_id,
    content: post.content || '',
    topic_pillar: post.topic_pillar || generationData.selected_pillars[0] || 'General',
    post_format: post.post_format || 'insight',
    hook: post.hook || '',
    estimated_words: post.estimated_words || 0
  }
}));

const saved = $input.first().json;
console.log(`✅ Post saved: ${saved.id} | client: ${saved.client_id}`);

// Notify connected dashboard clients via SSE
try {
  await fetch('http://localhost:5050/api/notify', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      event: 'new_posts',
      client_id: saved.client_id,
      count: 1
    })
  });
} catch(e) {
  console.log('Notify failed (non-critical):', e.message);
}

return [{ json: { success: true, post_id: saved.id } }];
